// that did not happen only drops something it did not need to, while one not
// told about a write that did keeps serving what the write replaced.
type observedPaymentRepository struct {
	PaymentRepository
	changes repox.ChangeObserver
}

func (o *observedPaymentRepository) Create(ctx context.Context, parent string, m *financepbv1.Payment) (*financepbv1.Payment, error) {
	out, err := o.PaymentRepository.Create(ctx, parent, m)
	o.created(ctx, m, out)
	return out, err
}

// created reports a Create: by the stored record's name, or failing that by
// the name the caller asked for. A Create that failed before naming anything
// wrote nothing.
func (o *observedPaymentRepository) created(ctx context.Context, m, out *financepbv1.Payment) {
	switch {
	case out.GetName() != "":
		o.changes.Changed(ctx, out.GetName())
	case m.GetName() != "":
		o.changes.Changed(ctx, m.GetName())
	}
}

func (o *observedPaymentRepository) Update(ctx context.Context, m *financepbv1.Payment, paths []string) (*financepbv1.Payment, error) {
	out, err := o.PaymentRepository.Update(ctx, m, paths)
	o.changes.Changed(ctx, m.GetName())
	return out, err
}

func (o *observedPaymentRepository) UpdateOutputOnly(ctx context.Context, m *financepbv1.Payment, paths []string) (*financepbv1.Payment, error) {
	out, err := o.PaymentRepository.UpdateOutputOnly(ctx, m, paths)
	o.changes.Changed(ctx, m.GetName())
	return out, err
}

func (o *observedPaymentRepository) UpdateWithOutputOnly(ctx context.Context, m *financepbv1.Payment, paths, outputPaths []string) (*financepbv1.Payment, error) {
	out, err := o.PaymentRepository.UpdateWithOutputOnly(ctx, m, paths, outputPaths)
	o.changes.Changed(ctx, m.GetName())
	return out, err
}

func (o *observedPaymentRepository) Delete(ctx context.Context, name string) error {
	err := o.PaymentRepository.Delete(ctx, name)
	o.changes.Changed(ctx, name)
	return err
}

// projectedInvoiceRepository runs the connection's projections over every
// Invoice write; see WithProjections. run performs a write through the
// repository it hands f and projects the changes f reports.
type projectedInvoiceRepository struct {
	InvoiceRepository
	run func(ctx context.Context, f func(InvoiceRepository) ([]repox.Change, error)) error
}

// getInvoice reads name through read, for a queued write's
// Change.LoadPrior (repox.PriorOf).
func getInvoice(ctx context.Context, read repox.Conn, name string) (*financepbv1.Invoice, error) {
	return New(read).Invoices.Get(ctx, name)
}

// changedInvoice is the change one write of a Invoice makes.
func changedInvoice(name string, op repox.ChangeOp, rec *financepbv1.Invoice) []repox.Change {
	c := repox.Change{Type: "aperio.finance.v1/Invoice", Name: name, Op: op}
	if rec != nil {
		c.Record = rec
	}
	return []repox.Change{c}
}

func (p *projectedInvoiceRepository) Create(ctx context.Context, parent string, m *financepbv1.Invoice) (out *financepbv1.Invoice, err error) {
	err = p.run(ctx, func(r InvoiceRepository) ([]repox.Change, error) {
		var err error
		out, err = r.Create(ctx, parent, m)
		return changedInvoice(out.GetName(), repox.ChangeCreate, out), err
	})
	return out, err
}

func (p *projectedInvoiceRepository) Update(ctx context.Context, m *financepbv1.Invoice, paths []string) (out *financepbv1.Invoice, err error) {
	err = p.run(ctx, func(r InvoiceRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.Update(ctx, m, paths)
		return repox.WithPrior(changedInvoice(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedInvoiceRepository) UpdateOutputOnly(ctx context.Context, m *financepbv1.Invoice, paths []string) (out *financepbv1.Invoice, err error) {
	err = p.run(ctx, func(r InvoiceRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.UpdateOutputOnly(ctx, m, paths)
		return repox.WithPrior(changedInvoice(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedInvoiceRepository) UpdateWithOutputOnly(ctx context.Context, m *financepbv1.Invoice, paths, outputPaths []string) (out *financepbv1.Invoice, err error) {
	err = p.run(ctx, func(r InvoiceRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, m.GetName()))
		if err != nil {
			return nil, err
		}
		out, err = r.UpdateWithOutputOnly(ctx, m, paths, outputPaths)
		return repox.WithPrior(changedInvoice(m.GetName(), repox.ChangeUpdate, out), prior), err
	})
	return out, err
}

func (p *projectedInvoiceRepository) Delete(ctx context.Context, name string) error {
	return p.run(ctx, func(r InvoiceRepository) ([]repox.Change, error) {
		prior, err := repox.Prior(r.Get(ctx, name))
		if err != nil {
			return nil, err
		}
		return repox.WithPrior(changedInvoice(name, repox.ChangeDelete, nil), prior), r.Delete(ctx, name)
	})
}

