// guardedInvoiceRepository keeps Invoice's references whole; see guard.
type guardedInvoiceRepository struct {
	InvoiceRepository
	refs *repox.References
}

func (g *guardedInvoiceRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "aperio.finance.v1/Invoice", name)
	if err != nil {
		return err
	}
	if err := g.InvoiceRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

// resolveInvoiceReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveInvoiceReferences(ctx context.Context, refs *repox.References, m *financepbv1.Invoice, paths []string) error {
	return nil
}

// queueInvoiceReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueInvoiceReferences(u *repox.Unit, m *financepbv1.Invoice, paths []string) {
}

// queueInvoiceDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueInvoiceDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "aperio.finance.v1/Invoice", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

// guardedPaymentRepository keeps Payment's references whole; see guard.
type guardedPaymentRepository struct {
	PaymentRepository
	refs *repox.References
}

func (g *guardedPaymentRepository) Create(ctx context.Context, parent string, m *financepbv1.Payment) (*financepbv1.Payment, error) {
	if err := resolvePaymentReferences(ctx, g.refs, m, nil); err != nil {
		return nil, err
	}
	return g.PaymentRepository.Create(ctx, parent, m)
}

func (g *guardedPaymentRepository) Update(ctx context.Context, m *financepbv1.Payment, paths []string) (*financepbv1.Payment, error) {
	if err := resolvePaymentReferences(ctx, g.refs, m, paths); err != nil {
		return nil, err
	}
	return g.PaymentRepository.Update(ctx, m, paths)
}

func (g *guardedPaymentRepository) UpdateWithOutputOnly(ctx context.Context, m *financepbv1.Payment, paths, outputPaths []string) (*financepbv1.Payment, error) {
	if err := resolvePaymentReferences(ctx, g.refs, m, paths); err != nil {
		return nil, err
	}
	return g.PaymentRepository.UpdateWithOutputOnly(ctx, m, paths, outputPaths)
}

func (g *guardedPaymentRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "aperio.finance.v1/Payment", name)
	if err != nil {
		return err
	}
	if err := g.PaymentRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

// resolvePaymentReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolvePaymentReferences(ctx context.Context, refs *repox.References, m *financepbv1.Payment, paths []string) error {
	if refs == nil {
		return nil
	}
	if repox.InMask(paths, "recorder") {
		if err := refs.Resolve(ctx, "recorder", "users.shokki.engineering/User", m.GetRecorder()); err != nil {
			return err
		}
	}
	return nil
}

// queuePaymentReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queuePaymentReferences(u *repox.Unit, m *financepbv1.Payment, paths []string) {
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error { return resolvePaymentReferences(ctx, refs, m, paths) })
	}
}

// queuePaymentDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queuePaymentDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "aperio.finance.v1/Payment", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}
